public class InnerCapacityProviderInstanceLaunchTemplateFactory(Action<Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate> factoryAction = null) : SubResourceFactory<Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate>
{

    internal InnerCapacityProviderManagedInstancesStorageConfigurationFactory StorageConfigurationFactory { get; set; }

    internal InnerCapacityProviderManagedInstancesNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    internal InnerCapacityProviderInstanceRequirementsRequestFactory InstanceRequirementsFactory { get; set; }

    internal InnerCapacityProviderCapacityReservationRequestFactory CapacityReservationsFactory { get; set; }

    internal InnerCapacityProviderManagedInstancesLocalStorageConfigurationFactory LocalStorageConfigurationFactory { get; set; }

    protected override Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate Create()
    {
        var instanceLaunchTemplateResult = CreateInstanceLaunchTemplate();
        factoryAction?.Invoke(instanceLaunchTemplateResult);

        return instanceLaunchTemplateResult;
    }

    private Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate CreateInstanceLaunchTemplate()
    {
        var instanceLaunchTemplateResult = new Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate();

        return instanceLaunchTemplateResult;
    }
    public override void CreateChildren(Humidifier.ECS.CapacityProviderTypes.InstanceLaunchTemplate result)
    {
        base.CreateChildren(result);

        result.StorageConfiguration ??= StorageConfigurationFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
        result.InstanceRequirements ??= InstanceRequirementsFactory?.Build();
        result.CapacityReservations ??= CapacityReservationsFactory?.Build();
        result.LocalStorageConfiguration ??= LocalStorageConfigurationFactory?.Build();
    }

} // End Of Class

